def need(ok,message):
 if not ok:raise ValueError(message)
def same(a,b):
 if type(a) is not type(b):return False
 if type(b) is dict:return set(a)==set(b) and all(same(a[k],v) for k,v in b.items())
 if type(b) is list:return len(a)==len(b) and all(same(x,y) for x,y in zip(a,b))
 return a==b
def unique(pairs):
 result={}
 for k,v in pairs:need(k not in result,'duplicate JSON key');result[k]=v
 return result
def nonfinite(token):raise ValueError('nonfinite JSON')
def number(token):
 x=float(token);need(math.isfinite(x),'nonfinite float');return x
def parse(raw):return json.loads(raw,object_pairs_hook=unique,parse_constant=nonfinite,parse_float=number)
def identities():
 return [('check_case.py',None)]+[('check_case.py',m) for m in sorted(REASONS)]
def wanted(index,mutation,mode):
 if mutation is None:return dict(status='PASS',optimization=mode,mutation='positive',result={'status': 'PASS_FINITE_CONSISTENCY_ONLY', 'cone_cases': 200, 'generic_orbit_samples': 8, 'kawasaki_l': [1, 2, 4, 8, 8], 'rational_pairing': '1/8', 'sphere_bundle_degrees': [0, 2, 5, 7], 'mv_cokernel_rank': 1, 'matrix_injectivity_cases': 17, 'original_target': 'UNRESOLVED', 'scope': 'Finite checks support the written audit; they do not prove local PL models, all inputs, or novelty.'})
 return dict(status='FAIL',optimization=mode,mutation=mutation,diagnostic=REASONS[mutation])
